package com.ultras.bans.listener;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.model.PunishmentType; import org.bukkit.event.*; import org.bukkit.event.player.*; import org.bukkit.entity.Player; import java.net.InetSocketAddress;
public final class PlayerListener implements Listener {private final ULTRASBansPlugin p;public PlayerListener(ULTRASBansPlugin p){this.p=p;}@EventHandler public void join(PlayerJoinEvent e){Player x=e.getPlayer();p.players().track(x,true);p.punishments().refresh(x);InetSocketAddress a=x.getAddress();if(a!=null)p.database().activeIp(a.getAddress().getHostAddress()).thenAccept(v->{if(v.isPresent())x.getServer().getScheduler().runTask(p,()->x.kick(com.ultras.bans.utility.Text.c("<red>ᴜʟᴛʀᴀs</red> | Your IP is banned.<br><gray>Reason: "+v.get().reason()+"</gray>")));});}@EventHandler public void quit(PlayerQuitEvent e){p.players().track(e.getPlayer(),false);}@EventHandler(priority=EventPriority.HIGHEST) public void move(PlayerMoveEvent e){p.freeze().move(e);if(!e.isCancelled())p.jail().move(e.getPlayer());}@EventHandler public void cmd(PlayerCommandPreprocessEvent e){if(p.freeze().isFrozen(e.getPlayer().getUniqueId())&&!e.getPlayer().hasPermission("ultrasbans.freeze"))e.setCancelled(true);}}
